 void shelf(){click("materialInputShelf");auto &list=get<QListWidget>("shelfAssets");QListWidgetItem *found=nullptr;for(int i=0;i<list.count();++i)if(list.item(i)->text().contains("material-source")){found=list.item(i);break;}require(found,"Applied original missing from real Shelf");list.setCurrentItem(found);list.scrollToItem(found);visible(list);const auto point=list.visualItemRect(found).center();for(auto kind:{QEvent::MouseButtonPress,QEvent::MouseButtonRelease,QEvent::MouseButtonDblClick,QEvent::MouseButtonRelease}){QMouseEvent event(kind,point,list.viewport()->mapToGlobal(point),Qt::LeftButton,kind==QEvent::MouseButtonRelease?Qt::NoButton:Qt::LeftButton,Qt::NoModifier);QApplication::sendEvent(list.viewport(),&event);}require(hooks_.state()["texture_loading"].toBool(),"Real Shelf double click did not start the shared loader");}
