  require(payloads==1&&aliases==0&&carrier,"sRGB stock file duplicated encoding or retained runtime aliases");Material *owner=nullptr;for(const auto &stored:document.texture_sets())if(stored.id==set().id)for(Material &m:main.materials)if(m.id.session_uid==stored.material_session_uid)owner=&m;require(owner,"Stock sRGB selected owner missing");
  pd149_sources_test::StockSavedImages audit;audit.audited.insert(carrier);
  for(const auto &node:owner->nodetree->nodes)if(node.id&&STREQ(node.idname,"ShaderNodeTexImage")&&(STRPREFIX(node.name,"__BTS_UserPixels")||STREQ(node.name,"__BTS_AOPixels"))){bool owned=false;for(Image &image:main.images)if(&image.id==node.id){audit.audited.insert(&image);owned=true;}require(owned,"Stock opacity/AO Image outside Main");}
  QJsonArray rows;double maximum=0,runtime_delta=0;const auto expected=captures_.last().toObject()["probes"].toArray();require(expected.size()==32,"Stock sRGB expected shape");
  hooks_.host.with_gpu([&]{std::array<std::unique_ptr<pd149_sources_test::SourceGpuTap>,4> taps;for(int c=0;c<4;++c)taps[c]=std::make_unique<pd149_sources_test::SourceGpuTap>(*owner,pd149_sources_test::Output(c),128,128,audit);
   int row=0;for(int tile:{1001,1002}){std::array<std::vector<std::array<float,4>>,4> values;for(int c=0;c<4;++c){values[c]=taps[c]->sample(tile);require(values[c].size()==128*128,"Stock sRGB packet shape");}for(int y:{19,51,83,115})for(int x:{13,45,77,109}){const auto reference=expected[row++].toObject();require(reference["tile"].toInt()==tile&&reference["xy"].toArray()==QJsonArray{x,y},"Stock sRGB expected position");const auto independent=reference["independent"].toArray(),runtime=reference["actual"].toArray();require(independent.size()==6&&runtime.size()==6,"Stock sRGB expected component shape");const int at=y*128+x;const std::array<double,6> actual{values[0][at][0],values[0][at][1],values[0][at][2],values[1][at][0],values[2][at][0],values[3][at][0]};QJsonArray observed;for(int c=0;c<6;++c){require(std::isfinite(actual[c])&&independent[c].isDouble()&&std::isfinite(independent[c].toDouble())&&runtime[c].isDouble()&&std::isfinite(runtime[c].toDouble()),"Stock sRGB nonfinite reference/value");maximum=std::max(maximum,std::abs(actual[c]-independent[c].toDouble()));runtime_delta=std::max(runtime_delta,std::abs(actual[c]-runtime[c].toDouble()));observed.append(actual[c]);}rows.append(QJsonObject{{"tile",tile},{"xy",QJsonArray{x,y}},{"actual",observed},{"independent",independent},{"runtime",runtime}});}}
  });
  stock_={{"observed",true},{"original_payloads",payloads},{"runtime_aliases",aliases},{"components",int(rows.size())*6},{"maximum_error",maximum},{"runtime_delta",runtime_delta},{"fixed_tolerance",3e-5},{"native_restore_called",false},{"canonical_alias_adaptation_called",false},{"probes",rows}};write(false);require(G_MAIN==live&&maximum<3e-5&&runtime_delta<3e-5,"Stock EOTF-before-filter sRGB differs from independent/runtime packet");
