std::function<void()> start_material_layering_ui_artist(QWidget *window,QWidget *viewport,const QString &output,const QString &mesh,int resolution,MaterialLayeringArtistHooks hooks){
 require(resolution==128,"PD149 source actor requires explicit128 resolution");if(qEnvironmentVariableIsSet("BTS_PD149_SURFACE_TEST")){require(qEnvironmentVariableIsSet("BTS_PD149_SURFACE_GRAPH_TEST")&&!qEnvironmentVariableIsSet("BTS_PD149_EEVEE_OBSERVATION")&&!qEnvironmentVariableIsSet("BTS_PD149_COLOR_UDIM_SOURCE")&&!qEnvironmentVariableIsSet("BTS_PD149_BUMP_SOURCE")&&!qEnvironmentVariableIsSet("BTS_PD149_MAP_SOURCE"),"Surface profile must be explicit and isolated");auto *actor=new SurfaceArtist(window,viewport,output,mesh,std::move(hooks));return [weak=QPointer<SurfaceArtist>(actor)]()noexcept{if(weak)weak->retire();};}if(qEnvironmentVariableIsSet("BTS_PD149_EEVEE_OBSERVATION")){require(!qEnvironmentVariableIsSet("BTS_PD149_COLOR_UDIM_SOURCE")&&!qEnvironmentVariableIsSet("BTS_PD149_BUMP_SOURCE")&&!qEnvironmentVariableIsSet("BTS_PD149_MAP_SOURCE"),"EEVEE observation must be a distinct actor profile");auto *actor=new EeveeObservationArtist(window,viewport,output,mesh,std::move(hooks));return [weak=QPointer<EeveeObservationArtist>(actor)]()noexcept{if(weak)weak->retire();};}if(qEnvironmentVariableIsSet("BTS_PD149_COLOR_UDIM_SOURCE")){auto *actor=new ColorUdimArtist(window,viewport,output,mesh,std::move(hooks));return [weak=QPointer<ColorUdimArtist>(actor)]()noexcept{if(weak)weak->retire();};}if(qEnvironmentVariableIsSet("BTS_PD149_BUMP_SOURCE")){auto *actor=new BumpArtist(window,viewport,output,mesh,std::move(hooks));return [weak=QPointer<BumpArtist>(actor)]()noexcept{if(weak)weak->retire();};}if(qEnvironmentVariableIsSet("BTS_PD149_MAP_SOURCE")){auto *actor=new MapsArtist(window,viewport,output,mesh,std::move(hooks));return [weak=QPointer<MapsArtist>(actor)]()noexcept{if(weak)weak->retire();};}auto *actor=new Artist(window,viewport,output,mesh,std::move(hooks));return [weak=QPointer<Artist>(actor)]()noexcept{if(weak)weak->retire();};
}
